def _canon(verb, path): return verb.lower(), tuple(snake(s.strip('{}')) if s.startswith('{') else snake(s) for s in path.strip('/').split('/'))

def _op_parts(path):
    "Snaked non-param segments, collection flag (path ends on a non-param segment), and param names"
    segs = path.strip('/').split('/')
    return [snake(s) for s in segs if not s.startswith('{')], not segs[-1].startswith('{'), [s.strip('{}') for s in segs if s.startswith('{')]

