def cf_names(spec):
    "Map each op's canonical (verb, snaked-segments) key to (group_segments, op_name), collision-free across the surface"
    ops = {}
    for p, item in spec['paths'].items():
        for v in item:
            if v in ('get','post','put','patch','delete','head','options'): ops.setdefault(_canon(v,p), p)
    gets = defaultdict(set)
    for (v,_),p in ops.items():
        g, coll, _ = _op_parts(p)
        if v=='get': gets[tuple(g)].add(coll)
    res = {}
    for k,p in ops.items():
        v = k[0]
        g, coll, ps = _op_parts(p)
        nm = 'list' if v=='get' and coll and len(gets[tuple(g)])==2 else v
        res[k] = [tuple(g), nm, ps]
    sibs = defaultdict(list)
    for k,(g,n,ps) in res.items(): sibs[(g,n)].append(k)
    for ks in sibs.values():
        if len(ks)==1: continue
        common = set.intersection(*(set(res[k][2]) for k in ks))
        for k in ks:
            extra = [q for q in res[k][2] if q not in common]
            if extra: res[k][1] += '_by_'+'_'.join(extra)
    opnms, kids = defaultdict(set), defaultdict(set)
    for g,n,_ in res.values():
        opnms[g].add(n)
        for i in range(1,len(g)): kids[g[:i]].add(g[i])
    for g,seg in [(g,s) for g in opnms for s in kids[g]&opnms[g]]:
        for k,(og,n,ps) in res.items():
            if og==g+(seg,): res[k] = [g, f'{seg}_{n}', ps]
    return {k:(list(g),n) for k,(g,n,ps) in res.items()}

