CF_OPENAPI_URL = 'https://raw.githubusercontent.com/cloudflare/api-schemas/main/openapi.json'

def build_spec(nm='fastcflare/cf_spec.py', url=CF_OPENAPI_URL):
    "Regenerate the compact spec module `cf_spec.py` from Cloudflare's OpenAPI schema."
    schema = dict2obj(json.loads(urlread(url)))
    SpecParser.from_openapi(schema, cf_group_func(cf_names(schema))).save(nm)

def _cf_spec():
    from fastcflare.cf_spec import spec
    return SpecParser.from_dict(spec)

